"""Build reviewed notes and question banks. Edit tools/content/*.json, never generated files.

Booklet selections are deliberately partial. Missing visual/table context, ambiguous
matches, incorrect answer blocks, duplicates and Paper Two practicals are withheld.
Original practice supplements topic coverage; it is not described as past-paper content.
"""
import argparse
import csv
import io
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import curriculum


def outputs():
    for subject in ('chemistry', 'computer', 'mathematics'):
        content = json.loads((ROOT / 'tools/content' / f'{subject}.json').read_text())
        topics = curriculum.get_subject(subject)['topics']
        assert set(content) == {t['slug'] for t in topics}, f'{subject}: topic coverage mismatch'
        rows = []
        if subject == 'chemistry':
            # Legacy input is read without altering its rows or order.
            with (ROOT / 'data/questions.csv').open(newline='') as f:
                rows.extend(dict(r) for r in csv.DictReader(f))
        for t in topics:
            entry = content[t['slug']]
            assert len(entry['principles'].split()) >= 90
            text = f"<!-- Generated by tools/build_teaching_content.py; edit the reviewed JSON. -->\n# {t['name']}\n\n"
            text += '## Core ideas and reasoning\n\n' + entry['principles'].strip() + '\n\n'
            text += '## Worked practice\n\n'
            for i, r in enumerate(entry['practice'], 1):
                assert r['question'].strip() and r['reference_answer'].strip()
                text += f"### Example {i}\n\n{r['question']}\n\n{r['reference_answer']}\n\n"
                rows.append({'question':r['question'], 'topic':t['slug'], 'reference_answer':r['reference_answer']})
            text += '## Check your reasoning\n\nExplain why the method applies before calculating or naming a result. Compare with a contrasting case. For calculations carry units, keep intermediate precision, then check by substitution, conservation or a second route. Describe observations separately from their explanation.\n'
            yield ROOT / 'data' / subject / 'notes' / (t['slug'] + '.md'), text
        fields = ['question','topic','concept','options','answer','explanation','reference_answer']
        buf = io.StringIO(newline='')
        w = csv.DictWriter(buf, fieldnames=fields, lineterminator='\n');w.writeheader()
        seen = set()
        for row in rows:
            if row['question'] in seen:
                raise ValueError('Duplicate question: ' + row['question'])
            seen.add(row['question'])
            w.writerow({k:row.get(k,'') for k in fields})
        yield ROOT / 'data' / subject / 'questions.csv', buf.getvalue()


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    failed=[]
    for path, text in outputs():
        if args.check:
            if not path.exists() or path.read_bytes() != text.encode():failed.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(text.encode())
    if failed:raise SystemExit('Outdated generated content: ' + ', '.join(failed))
    print('Content matches reviewed sources.' if args.check else 'Built teaching content for Chemistry, Computer Studies and Mathematics.')

if __name__ == '__main__':main()
